int l = 0, r = n - 1;
while (l < r) {
    swap(a[l], a[r]);
    l++; r--;                     // hands walk inward
}

// sorted => duplicates sit together
int write = 1;
for (int i = 1; i < n; i++)
    if (a[i] != a[i-1])           // new value discovered
        a[write++] = a[i];        // compact it forward
// 'write' = count of unique values

